1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	const CURSE_SURCHARGE_RATE = 0.5;
27	const HIGH_ENCHANTMENT_THRESHOLD = 5;
28	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	const BLOCK_SIZE = 3;
40	const BLOCK_PREMIUM = 60;
41	
42	/** Items that share the same `type`, and so are priced together. */
43	type AlikeItems = { type: string; items: Item[] };
44	
45	const groupByType = (items: Item[]): AlikeItems[] => {
46	  const itemsByType = new Map<string, Item[]>();
47	  for (const item of items) {
48	    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
49	  }
50	  return [...itemsByType].map(([type, alike]) => ({ type, items: alike }));
51	};
52	
53	const formsBlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
54	
55	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
56	
57	const basePremiumFor = ({ items }: AlikeItems): number =>
58	  formsBlock(items)
59	    ? BLOCK_PREMIUM
60	    : items.reduce((total, item) => total + itemBasePremium(item), 0);
61	
62	const totalBasePremium = (items: Item[]): number =>
63	  groupByType(items).reduce((total, alike) => total + basePremiumFor(alike), 0);
64	
65	/**
66	 * Sums `rate` × base premium over the items that `applies` to. Item-specific
67	 * surcharges are charged on the item's own base premium, never on the policy's,
68	 * so each one is an independent additive term.
69	 */
70	const perItemSurcharge = (
71	  items: Item[],
72	  applies: (item: Item) => boolean,
73	  rate: number,
74	): number =>
75	  items
76	    .filter(applies)
77	    .reduce((total, item) => total + itemBasePremium(item) * rate, 0);
78	
79	const isCursed = (item: Item): boolean => item.cursed === true;
80	
81	const totalCurseSurcharge = (items: Item[]): number =>
82	  perItemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);
83	
84	const isHighlyEnchanted = (item: Item): boolean =>
85	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
86	
87	const totalHighEnchantmentSurcharge = (items: Item[]): number =>
88	  perItemSurcharge(items, isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_RATE);
89	
90	const quotePremium = (items: Item[]): number => {
91	  const base = totalBasePremium(items);
92	  // Keep the surcharge additive (base + base * rate). The algebraically
93	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
94	  // which Math.ceil turns into a premium that is 1 G too high.
95	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
96	  return Math.ceil(
97	    base +
98	      totalCurseSurcharge(items) +
99	      totalHighEnchantmentSurcharge(items) +
100	      firstInsuranceSurcharge +
101	      PROCESSING_FEE,
102	  );
103	};
104	
105	export const runScenario = (scenario: Scenario): Result[] =>
106	  scenario.steps.map((step) => {
107	    if (step.op === "quote") return { premium: quotePremium(step.items) };
108	    throw new Error(`Unsupported step: ${step.op}`);
109	  });
